-- Gift ideas: the yearly gifting calendar (occasion, what to gift, and who to gift it to), from the TOFAA Gifting Calendar 2027.
-- Super admins manage the list through the API; every signed-in user reads the active ideas. The API uses the service role,
-- so RLS is on with no policies. This replaces the first, simpler version of the table (it held no data).
drop table if exists public.gift_ideas cascade;
create table public.gift_ideas (
    id uuid primary key default gen_random_uuid(),
    occasion text not null check (length(trim(occasion)) between 1 and 150),
    gift_idea text not null check (length(trim(gift_idea)) between 1 and 300),
    category text check (category is null or length(trim(category)) between 1 and 60),
    gift_to text[] not null default '{}',
    start_date date,
    end_date date,
    date_label text check (date_label is null or length(date_label) <= 80),
    is_active boolean not null default true,
    created_by_user_id uuid references public.profiles(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint gift_ideas_dates_ck check (end_date is null or (start_date is not null and end_date >= start_date))
);
create index gift_ideas_date_idx on public.gift_ideas(start_date nulls last, occasion);
create trigger gift_ideas_updated_at before update on public.gift_ideas
    for each row execute function public.handle_updated_at();
alter table public.gift_ideas enable row level security;


notify pgrst, 'reload schema';
